const body = $input.first().json.body || $input.first().json;
const { company_id, report_type, date_range, site_id, user_id } = body;

return {
  json: {
    report_id: body.run_id || crypto.randomUUID(),
    company_id,
    report_type: report_type || 'daily_summary',
    date_range: date_range || {},
    site_id,
    status: 'draft',
    generated_at: new Date().toISOString(),
    generated_by: user_id,
    source_records_linked: [],
    warnings: [],
    content: { title: report_type || 'Report', summary: 'Draft report - awaiting review and approval' }
  }
};
